<template><div class="product-interactions"><div class="toolbar"><span class="muted">商品详情查询会返回该商品下全部规格。此处按当前店铺与商品精确关联。</span><el-button size="small" @click="load">刷新交互记录</el-button><el-button type="text" @click="$router.push({path:'/oms-channel/platformLogs',query:{channelId,itemId,numberType:'PLATFORM_ITEM',number:itemId,allTime:'true',category:'PRODUCT'}})">前往统一交互日志</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table v-loading="loading" :data="rows" size="small"><el-table-column prop="create_time" label="时间" width="165"/><el-table-column label="操作 / 环境" min-width="200"><template slot-scope="s">{{ action(s.row) }}<div class="muted">{{ environments[s.row.environment] }} · {{ kinds[s.row.entry_kind] }} · {{ s.row.duration_ms }} ms</div></template></el-table-column><el-table-column label="结果" width="130"><template slot-scope="s"><el-tag size="mini" :type="s.row.result==='SUCCESS'?'success':'warning'">{{ results[s.row.result] }}</el-tag><div class="muted">{{ s.row.error_code }}</div></template></el-table-column><el-table-column width="110" label="操作"><template slot-scope="s"><el-button type="text" @click="open(s.row.id)">详情 / 报文</el-button></template></el-table-column></el-table><el-button v-if="cursor" type="text" @click="load(true)">加载更多</el-button>
<el-drawer title="商品平台交互与报文" :visible.sync="visible" size="min(1050px,96vw)" append-to-body :wrapper-closable="false"><el-alert v-if="detailError" :title="detailError" type="error" :closable="false"/><div v-if="detail" v-loading="detailLoading" class="workspace"><h3>{{ action(detail) }}</h3><el-descriptions :column="2" border size="small"><el-descriptions-item label="环境">{{ environments[detail.environment] }}</el-descriptions-item><el-descriptions-item label="时间">{{ detail.create_time }}</el-descriptions-item><el-descriptions-item label="请求编号">{{ detail.request_id }}</el-descriptions-item><el-descriptions-item label="平台请求号">{{ detail.platform_request_id || '—' }}</el-descriptions-item><el-descriptions-item label="本次调用">{{ results[detail.result] }} · {{ detail.duration_ms }} ms</el-descriptions-item><el-descriptions-item label="OMS 保存结果">{{ saveResult }}</el-descriptions-item></el-descriptions><h3>本次调用链路</h3><el-table :data="detail.chain" size="small" highlight-current-row @current-change="choose"><el-table-column label="操作"><template slot-scope="s">{{ action(s.row) }}<div class="muted">{{ kinds[s.row.entry_kind] }}</div></template></el-table-column><el-table-column label="结果" width="120"><template slot-scope="s">{{ results[s.row.result] }}</template></el-table-column><el-table-column prop="error_code" label="错误码"/><el-table-column label="报文"><template slot-scope="s"><el-button v-hasPermi="['channel:platform:payload']" type="text" @click="choose(s.row)">查看此条报文</el-button></template></el-table-column></el-table><div class="toolbar"><h3>脱敏请求与响应</h3><el-input v-model="keyword" placeholder="搜索报文内容" clearable size="small" style="width:220px"/></div><p class="muted">凭据、签名和个人信息已处理；超出记录限制时会显示截断提示。</p><el-alert v-if="payloadError" :title="payloadError" type="warning" :closable="false"/><template v-if="payload"><el-alert v-if="payload.expired" :title="payload.message" type="info" :closable="false"/><template v-else><el-alert v-if="payload.request_truncated||payload.response_truncated" title="报文已截断，未记录内容不会参与业务判断" type="warning" :closable="false"/><h4>请求 <el-button v-clipboard:copy="pretty(payload.request_json)" type="text">复制</el-button></h4><pre>{{ filtered(payload.request_json) }}</pre><h4>响应 <el-button v-clipboard:copy="pretty(payload.response_json)" type="text">复制</el-button></h4><pre>{{ filtered(payload.response_json) }}</pre></template></template><p v-else-if="!payloadLoading" class="muted">选择链路中的记录查看报文；读取权限沿用统一日志权限。</p></div></el-drawer></div></template>
<script>
import {platformGet} from '@/api/channel/platform'
import {actions,kinds,environments,results} from './platformLogLabels'
export default {name:'ProductInteractions',props:{channelId:[Number,String],itemId:String},data(){return{actions,kinds,environments,results,rows:[],cursor:'',error:'',loading:false,visible:false,detail:null,detailError:'',detailSeq:0,detailLoading:false,payload:null,payloadError:'',payloadLoading:false,keyword:'',seq:0,payloadSeq:0}},computed:{saveResult(){const root=(this.detail.chain||[]).find(x=>x.action==='PRODUCT_DETAIL');return root?root.result==='SUCCESS'?'已保存商品快照':root.result==='FAILED'?'未保存，请查看失败记录':'保存结果待确认':'此操作不涉及商品快照保存'}},watch:{itemId:{immediate:true,handler(){this.load()}}},beforeDestroy(){this.seq++;this.payloadSeq++;this.detailSeq++},methods:{action(r){return actions[r.interface_name]||actions[r.action]||r.interface_name||r.action},async load(more=false){if(!this.channelId||!this.itemId)return;const seq=++this.seq;this.loading=true;this.error='';try{const r=await platformGet('/log-center',{channelId:this.channelId,numberType:'PLATFORM_ITEM',number:this.itemId,allTime:true,itemId:this.itemId,category:'PRODUCT',limit:50,cursor:more?this.cursor:''});if(seq===this.seq){const rows=r.data.rows.filter(x=>x.entry_kind!=='CONFIG');this.rows=more?[...this.rows,...rows]:rows;this.cursor=r.data.next_cursor}}catch(_){if(seq===this.seq)this.error='商品交互记录读取失败，请刷新重试'}finally{if(seq===this.seq)this.loading=false}},async open(id){const seq=++this.detailSeq;this.detailLoading=true;this.detail=null;this.detailError='';this.visible=true;this.payload=null;this.payloadSeq++;try{const d=(await platformGet('/log-center/'+id)).data;if(seq!==this.detailSeq)return;d.chain=(d.chain||[]).filter(r=>r.root_request_id===d.root_request_id);this.detail=d;const api=['API','SIMULATION'].includes(d.entry_kind)?d:this.detail.chain.find(x=>['API','SIMULATION'].includes(x.entry_kind));if(api&&this.$auth.hasPermi('channel:platform:payload'))await this.choose(api)}catch(_){if(seq===this.detailSeq)this.detailError='交互详情读取失败，请关闭后重新选择记录'}finally{if(seq===this.detailSeq)this.detailLoading=false}},async choose(row){if(!row||!this.$auth.hasPermi('channel:platform:payload'))return;const seq=++this.payloadSeq;this.payload=null;this.payloadError='';this.payloadLoading=true;try{const r=await platformGet('/log-center/'+row.id+'/payload');if(seq===this.payloadSeq)this.payload=r.data}catch(_){if(seq===this.payloadSeq)this.payloadError='报文读取失败，请重新选择记录'}finally{if(seq===this.payloadSeq)this.payloadLoading=false}},pretty(v){try{return JSON.stringify(typeof v==='string'?JSON.parse(v):v,null,2)}catch(_){return String(v||'尚无报文')}},filtered(v){const text=this.pretty(v);return this.keyword?text.split('\n').filter(l=>l.toLowerCase().includes(this.keyword.toLowerCase())).join('\n')||'无匹配内容':text}}}
</script><style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:12px 0}.muted{color:#7f8b9d;font-size:13px;line-height:1.7}.workspace{padding:0 24px 30px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto;padding:16px;background:#f5f7fa}.workspace h3{margin-top:24px}</style>
